<main class="container py-4"><h1>Edit profile</h1><?php if ($error): ?><div class="alert alert-danger"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><form method="post" class="col-md-7"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrfToken(), ENT_QUOTES, 'UTF-8') ?>"><div class="mb-3"><label class="form-label">Name<input class="form-control" name="full_name" required maxlength="120" value="<?= htmlspecialchars((string)($_POST['full_name'] ?? $user['full_name']), ENT_QUOTES, 'UTF-8') ?>"></label></div><div class="mb-3"><label class="form-label">Email<input class="form-control" type="email" name="email" required maxlength="254" value="<?= htmlspecialchars((string)($_POST['email'] ?? $user['email']), ENT_QUOTES, 'UTF-8') ?>"></label></div><p>Role and status are managed separately.</p><button class="btn btn-primary">Save changes</button> <a class="btn btn-secondary" href="profile.php">Cancel</a></form></main><?php require __DIR__ . '/../includes/footer.php'; ?>
